package ai.heyu.agent;
import org.json.*;import java.math.*;import java.time.*;import java.util.*;
/** Every actionable number, source, coordinate and date is validated before local execution. */
final class NativeTaskRules {
 static final Set<String> KINDS=new HashSet<>(Arrays.asList("ppt","document","quote","analysis","image","translation","schedule"));
 static BigDecimal number(Object v)throws Exception{if(v==null||v==JSONObject.NULL||v instanceof Boolean)throw new Exception("缺少数字，不能用0代替");String s=String.valueOf(v).trim();if(!s.matches("-?(?:\\d{1,3}(?:,\\d{3})+|\\d+)(?:\\.\\d{1,6})?"))throw new Exception("数字格式不明确，最多6位小数");BigDecimal x=new BigDecimal(s.replace(",",""));if(x.abs().compareTo(new BigDecimal("1000000000"))>0)throw new Exception("数字过大");return x;}
 static String grounded(JSONObject o,String field,String source,int max)throws Exception{String x=NativeData.str(o,field,max);if(!source.contains(x))throw new Exception("字段缺少原文依据："+field);return x;}
 static boolean containsNumber(String text,BigDecimal n){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?<![\\d.])-?(?:\\d{1,3}(?:,\\d{3})+|\\d+)(?:\\.\\d+)?(?![\\d.])").matcher(text);while(m.find())try{if(number(m.group()).compareTo(n)==0)return true;}catch(Exception ignored){}return false;}
 static int integer(JSONObject o,String key,int low,int high)throws Exception{Object v=o.opt(key);if(!(v instanceof Number))throw new Exception("整数参数缺失："+key);int n;try{n=new BigDecimal(v.toString()).intValueExact();}catch(ArithmeticException|NumberFormatException e){throw new Exception("整数参数无效："+key);}if(n<low||n>high)throw new Exception("参数超出范围："+key);return n;}
 static String formats(String kind){switch(kind){case "ppt":return "PPTX";case "quote":return "XLSX,PDF";case "analysis":return "XLSX,PNG";case "image":return "PNG/JPEG";case "schedule":return "DOCX,PDF,ICS（有日程时）";default:return "DOCX,PDF";}}
 static JSONObject validate(JSONObject plan,JSONArray materials,String source)throws Exception{
  String kind=plan.getString("kind");JSONObject spec=plan.getJSONObject("spec");Set<String> allowed=new HashSet<>();
  if(kind.equals("image"))allowed.add("image");else if(kind.equals("analysis"))allowed.add("table");else{allowed.add("text");if(kind.equals("quote"))allowed.add("table");}
  for(int i=0;i<materials.length();i++)if(!allowed.contains(materials.getJSONObject(i).getJSONObject("content").getString("type")))throw new Exception("所选材料与任务类型不匹配，不能悄悄忽略");
  switch(kind){
   case "ppt":integer(spec,"pages",3,10);NativeData.str(spec,"language",60);break;
   case "document":NativeData.str(spec,"language",60);break;
   case "quote":{
    String mode=spec.optString("mode");if(!mode.equals("quote")&&!mode.equals("list"))throw new Exception("报价或清单模式不明确");JSONArray items=spec.getJSONArray("items");if(items.length()<1||items.length()>60)throw new Exception("清单限1–60项");String currency=spec.optString("currency").toUpperCase(Locale.ROOT);
    if(mode.equals("quote")){Map<String,String> aliases=new HashMap<>();aliases.put("CNY","CNY|RMB|人民币|元");aliases.put("USD","USD|美元|US$");aliases.put("EUR","EUR|欧元|€");aliases.put("GBP","GBP|英镑|£");aliases.put("JPY","JPY|日元");aliases.put("HKD","HKD|港币|港元");aliases.put("SGD","SGD|新币|新加坡元");if(!aliases.containsKey(currency)||Arrays.stream(aliases.get(currency).split("\\|")).noneMatch(source::contains))throw new Exception("请明确币种，不根据地点猜测");}
    BigDecimal total=BigDecimal.ZERO;for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String evidence=grounded(item,"evidence",source,1500);String name=NativeData.str(item,"name",140);if(!evidence.contains(name))throw new Exception("产品名缺少来源");BigDecimal quantity=number(item.opt("quantity"));if(quantity.signum()<=0||!containsNumber(evidence,quantity))throw new Exception("数量无有效原文支持");item.put("quantity",quantity.toPlainString());String unit=item.optString("unit","");if(!unit.isEmpty()&&!evidence.contains(unit))throw new Exception("单位无原文支持");if(mode.equals("quote")){BigDecimal price=number(item.opt("unit_price"));if(price.signum()<0||!containsNumber(evidence,price))throw new Exception("单价无原文支持");BigDecimal amount=quantity.multiply(price).setScale(2,RoundingMode.HALF_UP);item.put("unit_price",price.toPlainString()).put("amount",amount.toPlainString());total=total.add(amount);}}
    spec.put("currency",currency).put("total",total.toPlainString());break;
   }
   case "translation":NativeData.str(spec,"target_language",60);if(!"bilingual".equals(spec.optString("mode")))throw new Exception("当前支持逐段双语翻译");if(materials.length()==0)throw new Exception("请选择要翻译的文字文件");break;
   case "analysis":{
    if(materials.length()!=1)throw new Exception("请选择一份表格");JSONObject src=materials.getJSONObject(0);if(!src.getString("id").equals(spec.optString("source_id")))throw new Exception("表格来源不匹配");JSONObject table=selectedTable(src,spec);Set<String> headers=set(table.getJSONArray("headers"));if(!headers.contains(spec.optString("group_column")))throw new Exception("分组列不存在");String agg=spec.optString("aggregation");if(!Arrays.asList("sum","count","average").contains(agg))throw new Exception("仅支持求和、计数或平均");if(!agg.equals("count")&&!headers.contains(spec.optString("value_column")))throw new Exception("计算列不存在");integer(spec,"top_n",1,30);if(!Arrays.asList("asc","desc").contains(spec.optString("order")))throw new Exception("排序方式不明确");JSONArray filters=spec.optJSONArray("filters");if(filters==null||filters.length()>3)throw new Exception("最多3个AND过滤条件");for(int i=0;i<filters.length();i++){JSONObject f=filters.getJSONObject(i);if(!headers.contains(f.optString("column"))||!Arrays.asList("eq","gt","gte","lt","lte").contains(f.optString("operator")))throw new Exception("过滤列或方式无效");if(!source.contains(f.optString("value")))throw new Exception("过滤值必须在任务来源中");}break;
   }
   case "image":{
    if(materials.length()==0||materials.length()>4)throw new Exception("图片需1–4张");JSONArray ops=spec.getJSONArray("operations");if(ops.length()<1||ops.length()>8)throw new Exception("图片操作需1–8步");int width=materials.getJSONObject(0).getJSONObject("content").getInt("width"),height=materials.getJSONObject(0).getJSONObject("content").getInt("height");boolean jpeg=false;
    for(int i=0;i<ops.length();i++){JSONObject op=ops.getJSONObject(i);switch(op.optString("op")){
     case "collage":if(i!=0||materials.length()<2||!Arrays.asList("horizontal","vertical","grid").contains(op.optString("layout")))throw new Exception("拼图需至少2图且必须是第一步");int maxW=0,maxH=0,sumW=0,sumH=0;for(int n=0;n<materials.length();n++){JSONObject m=materials.getJSONObject(n).getJSONObject("content");maxW=Math.max(maxW,m.getInt("width"));maxH=Math.max(maxH,m.getInt("height"));sumW+=m.getInt("width");sumH+=m.getInt("height");}String layout=op.getString("layout");width=layout.equals("horizontal")?sumW:layout.equals("vertical")?maxW:2*maxW;height=layout.equals("horizontal")?maxH:layout.equals("vertical")?sumH:((materials.length()+1)/2)*maxH;break;
     case "resize":int w=integer(op,"width",1,4096);if(!containsNumber(source,new BigDecimal(w)))throw new Exception("缩放宽度需要原文确认");height=Math.max(1,(int)Math.round((double)height*w/width));width=w;break;
     case "crop":JSONArray box=box(op.getJSONArray("box"),width,height,source);width=box.getInt(2)-box.getInt(0);height=box.getInt(3)-box.getInt(1);break;
     case "rotate":int d=integer(op,"degrees",0,270);if(d%90!=0||!containsNumber(source,new BigDecimal(d)))throw new Exception("旋转角度需明确为0/90/180/270");if(d==90||d==270){int t=width;width=height;height=t;}break;
     case "watermark":String mark=NativeData.str(op,"text",80);if(!source.contains(mark))throw new Exception("水印文字没有原文支持");break;
     case "redact":JSONArray boxes=op.getJSONArray("boxes");if(boxes.length()<1||boxes.length()>20)throw new Exception("遮挡区域需1–20项");for(int n=0;n<boxes.length();n++)box(boxes.getJSONArray(n),width,height,source);break;
     case "compress":integer(op,"quality",1,100);jpeg=true;break;
     default:throw new Exception("不支持此图片操作，未执行");}
     if(width<=0||height<=0||(long)width*height>12000000)throw new Exception("输出图片像素过大");
    }if(materials.length()>1&&!"collage".equals(ops.getJSONObject(0).optString("op")))throw new Exception("多图仅支持明确拼图");spec.put("output_width",width).put("output_height",height).put("jpeg",jpeg);break;
   }
   case "schedule":{
    JSONArray items=spec.getJSONArray("items"),events=spec.getJSONArray("events");if(items.length()+events.length()<1||items.length()>30||events.length()>10)throw new Exception("待办或日程范围异常");String zone=plan.getString("timezone");ZoneId zid=ZoneId.of(zone);
    for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String ev=grounded(item,"evidence",source,1500);for(String field:new String[]{"task","owner","due"}){String v=item.optString(field,"");if(field.equals("task")&&v.codePoints().allMatch(Character::isWhitespace)||!v.isEmpty()&&!ev.contains(v))throw new Exception("待办字段没有原文依据："+field);}}
    for(int i=0;i<events.length();i++){JSONObject event=events.getJSONObject(i);String ev=grounded(event,"evidence",source,1500);String date=grounded(event,"date_evidence",source,300);String title=NativeData.str(event,"title",160);if(!ev.contains(title))throw new Exception("日程标题缺少依据");LocalDateTime start=LocalDateTime.parse(event.getString("start")),end=LocalDateTime.parse(event.getString("end"));if(!end.isAfter(start)||java.time.Duration.between(start,end).toDays()>7)throw new Exception("日程起止时间无效");if(!date.contains(start.toLocalDate().toString())||!date.contains(start.toLocalTime().toString())||!date.contains(end.toLocalTime().toString()))throw new Exception("请提供日程绝对日期和起止时间，不能推测");if(zid.getRules().getValidOffsets(start).size()!=1||zid.getRules().getValidOffsets(end).size()!=1)throw new Exception("时区时间有歧义，请明确时间");String loc=event.optString("location","");if(!loc.isEmpty()&&!ev.contains(loc))throw new Exception("日程地点缺少依据");event.put("startMs",start.atZone(zid).toInstant().toEpochMilli()).put("endMs",end.atZone(zid).toInstant().toEpochMilli());}break;
   }
   default:throw new Exception("未知任务类型");
  }
  return spec;
 }
 static JSONArray box(JSONArray b,int w,int h,String source)throws Exception{if(b.length()!=4)throw new Exception("图片坐标需左上右下四个整数");for(int n=0;n<4;n++){Object v=b.get(n);if(!(v instanceof Integer)||!containsNumber(source,new BigDecimal((Integer)v)))throw new Exception("坐标需要明确来源");}if(b.getInt(0)<0||b.getInt(1)<0||b.getInt(2)>w||b.getInt(3)>h||b.getInt(2)<=b.getInt(0)||b.getInt(3)<=b.getInt(1))throw new Exception("图片区域超出边界");return b;}
 static Set<String> set(JSONArray a){Set<String> s=new HashSet<>();for(int i=0;i<a.length();i++)s.add(a.optString(i));return s;}
 static int index(JSONArray a,String value)throws Exception{for(int i=0;i<a.length();i++)if(a.getString(i).equals(value))return i;throw new Exception("列不存在");}
 static JSONObject selectedTable(JSONObject material,JSONObject spec)throws Exception{JSONArray tables=material.getJSONObject("content").getJSONArray("tables");for(int i=0;i<tables.length();i++)if(tables.getJSONObject(i).getString("sheet").equals(spec.optString("sheet")))return tables.getJSONObject(i);throw new Exception("工作表不存在");}
 static JSONObject analyze(JSONObject table,JSONObject spec)throws Exception{
  JSONArray headers=table.getJSONArray("headers"),data=table.getJSONArray("rows"),filters=spec.getJSONArray("filters");String agg=spec.getString("aggregation");int group=index(headers,spec.getString("group_column")),metric=agg.equals("count")?-1:index(headers,spec.getString("value_column"));Map<String,BigDecimal> sums=new LinkedHashMap<>();Map<String,JSONArray> members=new LinkedHashMap<>();int used=0;
  for(int i=0;i<data.length();i++){JSONArray row=data.getJSONArray(i);boolean include=true;for(int n=0;n<filters.length();n++){JSONObject f=filters.getJSONObject(n);Object value=row.get(index(headers,f.getString("column")));String op=f.getString("operator");if(op.equals("eq")){if(!String.valueOf(value).equals(f.getString("value")))include=false;}else{int compare=number(value).compareTo(number(f.get("value")));if(op.equals("gt")&&compare<=0||op.equals("gte")&&compare<0||op.equals("lt")&&compare>=0||op.equals("lte")&&compare>0)include=false;}}
   if(!include)continue;String name=row.optString(group);if(name.codePoints().allMatch(Character::isWhitespace))throw new Exception("分组列存在空值");BigDecimal value=agg.equals("count")?BigDecimal.ONE:number(row.get(metric));sums.put(name,sums.getOrDefault(name,BigDecimal.ZERO).add(value));if(!members.containsKey(name))members.put(name,new JSONArray());members.get(name).put(i+2);used++;
  }
  if(used==0)throw new Exception("筛选后没有数据");List<JSONObject> rows=new ArrayList<>();for(String name:sums.keySet()){BigDecimal value=sums.get(name);if(agg.equals("average"))value=value.divide(new BigDecimal(members.get(name).length()),10,RoundingMode.HALF_UP);rows.add(AgentApi.obj("label",name,"value",value.stripTrailingZeros().toPlainString(),"count",members.get(name).length(),"source_rows",members.get(name)));}
  boolean desc=spec.getString("order").equals("desc");rows.sort((a,b)->{int value=new BigDecimal(a.optString("value")).compareTo(new BigDecimal(b.optString("value")));return desc?-value:value;});JSONArray all=new JSONArray(rows),top=new JSONArray();for(int i=0;i<Math.min(spec.getInt("top_n"),rows.size());i++)top.put(rows.get(i));return AgentApi.obj("all_rows",all,"rows",top,"used_rows",used,"input_rows",data.length());
 }
}
